"""Render three saved actual portfolios from one immutable preliminary snapshot."""
from collections import Counter
import json,html
from pathlib import Path
from backend.app.product_services.scenario_allocation import dependence_audit

ROOT=Path('research/scenario_first_sunday_main_20261014');PRIOR=Path('research/sunday_main_merged_comparison_20261013')
def name(p):return p.get('name',p.get('player_name',p['player_id']))
def sig(l):return tuple(sorted(str(p['player_id']) for p in l))
def total(l,k):return sum(float(p[k]) for p in l)
def main():
    reports={'Old CONSTRUCTION':json.loads((PRIOR/'old_result_v2.json').read_text()),'Prior merged coverage':json.loads((PRIOR/'merged_result_v3.json').read_text()),'Scenario first':json.loads((ROOT/'result.json').read_text())}
    fresh=reports['Scenario first'];engine=fresh['football_analyst'];plan=engine['scenario_allocation_plan'];worlds=engine['scenario_definitions'];rows=engine['input_snapshot']['players'];lookup={str(r['player_id']):r for r in rows};ideas={i['idea_id']:i for i in plan['ideas']};snapshot=json.loads((PRIOR/'preliminary_snapshot_receipt.json').read_text());exposures={};checks={};audits={};scores={}
    for arm,r in reports.items():
        assert r['status']=='completed' and r['entry_readiness']['entry_ready'] is False
        assert r['projection_run_id']==snapshot['projection_run_id'] and r['preliminary_report']['snapshot_sha256']==snapshot['snapshot_sha256']
        assert r['preliminary_report']['assumption_manifest_sha256']==snapshot['assumption_manifest_sha256']
        exposures[arm]=Counter(str(p['player_id']) for l in r['results'] for p in l)
        candidates=[dict(allocated_idea_id=(l[0].get('analyst_allocated_idea_id') or 'legacy_unallocated'),roster=[dict(player_master_id=str(p['player_id'])) for p in l]) for l in r['results']]
        audits[arm]=dependence_audit(candidates,rows,5)
        scores[arm]=[{w['scenario_id']:sum(w['moments'][str(p['player_id'])]['mean']+.35*(w['moments'][str(p['player_id'])]['p90']-w['moments'][str(p['player_id'])]['mean']) for p in l) for w in worlds} for l in r['results']]
        for l in r['results']:
            assert len(sig(l))==len(set(sig(l)))==9 and total(l,'salary')<=50000
            assert Counter(p['position'] for p in l)['QB']==1 and Counter(p['position'] for p in l)['TE']==1 and Counter(p['position'] for p in l)['DST']==1
            for p in l:assert abs(float(p['projection'])-float(lookup[str(p['player_id'])]['projection']))<1e-7
        checks[arm]=dict(achieved=len(r['results']),run_id=r['job_id'],same_snapshot=True,base_means_unchanged=True,entry_ready=False)
    assert all(c['construction_audit']['passed'] for c in engine['candidates'])
    assert not audits['Scenario first']['all_lineups_share_three_players']
    evidence=dict(classification='PRELIMINARY_RESEARCH',entry_ready=False,experiment_kind='generation_and_selection_comparison',identical_candidate_pools=False,snapshot_sha256=snapshot['snapshot_sha256'],packet_sha256=engine['packet_sha256'],checks=checks,allocation_plan=plan,actual_dependence_audits=audits,conditional_scores=scores,exposures={arm:dict(e) for arm,e in exposures.items()},limits='Design priorities/conditional opportunity sensitivities are uncalibrated. Greedy sequential legal construction can underfill despite an undiscovered feasible portfolio. No future performance claim.')
    (ROOT/'comparison.json').write_text(json.dumps(evidence,indent=2,allow_nan=False)+'\n')
    lines=['# Sunday Main: scenario-first correction','', '**PRELIMINARY RESEARCH — not entry cleared.** All three portfolios use the same actual frozen salary/projection/ownership and explicit injury assumptions. Current-questionable players are excluded; missing official practice evidence stays ERROR. No healthy inference, CSV export or contest submission.','', 'The old construction and prior merged coverage portfolios both retained Puka Nacua, Tyler Higbee and Kyren Williams in all five lineups. The new portfolio commits evidence-ranked football ideas before legal roster solves, then constrains and audits actual shared player dependence. Different names alone do not count as different outcomes.','', '## Allocation before player optimization','', '| Slot | Planned football idea | Actual idea | Priority | Next credible alternative |','|---|---|---|---:|---|']
    for s in plan['slots']:lines.append(f"| {s['slot']} | {s['idea_id']} | {s.get('actual_idea_id','UNDERFILLED')} | {s['priority_score']:.3f} | {(s.get('next_credible_alternative') or {}).get('idea_id','none')} |")
    lines+=['','Priority is a disclosed ordinal design score: role capability, measured usage coverage, source support and analyst ranking, discounted for repeated game/idea dependence and credited for a distinct script. These are not outcome probabilities or equal game quotas. Infeasible planned ideas try the next credible alternative under unchanged hard constraints; every attempt is saved.','', 'Passing construction requires the supported primary QB and measured receiver; run control requires the primary RB, no primary QB and at most one primary receiver. Other teams have at most two offensive players per roster. Opponent response is required only when the sourced two-sided passing branch and projected/observed capability support it. Same-team receiver pairs and canonical triples may appear in at most three of five lineups by default; explicit all-player locks take priority.','', 'The 100-unit skill opportunity budget conserves targets plus carries. The conditional script moves 12 units between passing and rushing, with opposite ratios and bounded 0.7 fantasy response sensitivity. Missing complete target/carry coverage uses an explicitly disclosed 55/45 design prior. It is not a forecast of 100 NFL attempts. Base projections remain unchanged.','', '## Actual saved portfolios','']
    tables=[]
    for arm,r in reports.items():
        lines+=['### '+arm,'',f"Saved run `{r['job_id']}` — {len(r['results'])}/5 lineups.",'','| # | QB | RB | WR | TE | DST | Salary | Base mean | Conditional score / allocated idea |','|---|---|---|---|---|---|---:|---:|---|'];trs=[]
        for n,l in enumerate(r['results'],1):
            idea=l[0].get('analyst_allocated_idea_id');metric=f"{scores[arm][n-1][idea]:.2f} / {idea}" if idea else 'Legacy comparison; no allocated idea'
            cells=[str(n)]+[', '.join(name(p) for p in l if p['position']==pos) for pos in ['QB','RB','WR','TE','DST']]+[f"${total(l,'salary'):,.0f}",f"{total(l,'projection'):.2f}",metric];lines.append('| '+' | '.join(cells)+' |');trs.append('<tr>'+''.join('<td>'+html.escape(c)+'</td>' for c in cells)+'</tr>')
        lines+=[''];tables.append('<h2>'+html.escape(arm)+'</h2><p>Saved run '+r['job_id']+'</p><div class="scroll"><table><tr>'+''.join('<th>'+h+'</th>' for h in ['#','QB','RB','WR','TE','DST','Salary','Base mean','Conditional / idea'])+'</tr>'+''.join(trs)+'</table></div>')
    lines+=['## Why the Rams core is no longer repeated','','The Rams passing idea earns the first slot. Its contrary run-control idea remains admitted, but its adjusted priority after the first Rams slot is 0.361; repeating Rams passing is 0.380. Kansas City run control earns the final slot at 0.792, with Indianapolis run control next at 0.757. Credible alternatives therefore displace both Rams repeats without a team-specific ban. Puka remains 5/5 because one receiver can fit different offensive scripts as an independent secondary value; the portfolio no longer requires the Puka/Higbee/Kyren triple in every lineup. These are explicit dependence proxies, not a fitted joint scoring covariance model.','','## New roster construction evidence','','| Slot | Primary QB | Primary RB | Primary receivers | Opponent receivers | Secondary offense counts |','|---|---:|---:|---:|---:|---|']
    for c in engine['candidates']:
        a=c['construction_audit'];lines.append(f"| {c['allocation_slot']} | {a['primary_qb_count']} | {a['primary_rb_count']} | {a['primary_receiver_count']} | {a['opponent_receiver_count']} | {a['secondary_offense_counts']} |")
    lines+=['','## Individual new-lineup player values','']
    for n,l in enumerate(fresh['results'],1):
        lines += [f'### Scenario-first lineup {n}','','| Position | Player | Team | Salary | Base projected mean |','|---|---|---|---:|---:|']
        for p in l:lines.append(f"| {p['position']} | {name(p)} | {p['player_team']} | ${float(p['salary']):,.0f} | {float(p['projection']):.2f} |")
        lines.append('')
    lines+=['## Shared outcome dependence and exposures','','| Arm | Heavy offense teams (3+ players) | Largest receiving pair count | Largest triple count | All five share a triple? |','|---|---|---:|---:|---|']
    for arm,a in audits.items():lines.append(f"| {arm} | {a['heavy_team_offense_counts']} | {max([p['count'] for p in a['receiving_pairs']] or [0])} | {max([p['count'] for p in a['shared_triples']] or [0])} | {a['all_lineups_share_three_players']} |")
    lines+=['','| Player | Old /5 | Prior merged /5 | Scenario first /5 |','|---|---:|---:|---:|']
    for pid in sorted(set().union(*[set(e) for e in exposures.values()]),key=lambda p:(-max(e[p] for e in exposures.values()),name(lookup[p]))):lines.append('| '+name(lookup[pid])+' | '+' | '.join(str(e[pid]) for e in exposures.values())+' |')
    lines+=['','## Reviewable assumptions and limits','',f"Packet `{engine['packet_sha256']}`. Snapshot `{snapshot['snapshot_sha256']}`. Projection `{snapshot['projection_run_id']}`. Ownership `{snapshot['ownership_run_id']}`.",'', 'Five lineups; 100% player exposure ceiling; uniqueness two; team four/game five; single TE; favored RB/TE/DST; avoid DST opponents; QB/RB salary minimum $4,500; no locks/manual exclusions; season rank restrictions explicitly disabled in all arms because Week5 snap coverage is incomplete. New-path allocation/dependence controls are the declared treatment. Original/prior results are preserved, not reranked by the new objective.','', 'This compares generation and selection with different candidate pools. Conditional scores are sensitivity measures, not comparable to old solver objectives, lineup P90, calibrated EV or evidence of better future performance. The complete machine evidence records all considered/rejected ideas, conserved budgets, fallback solver statuses, actual compliance and common conditional scores for all three arms.','', '[Machine evidence](comparison.json) · [New saved API response](result.json) · [Prior comparison](../sunday_main_merged_comparison_20261013/LINEUP_COMPARISON.md)']
    (ROOT/'LINEUP_COMPARISON.md').write_text('\n'.join(lines)+'\n');(ROOT/'LINEUP_COMPARISON.html').write_text('<!doctype html><html><head><meta charset="utf-8"><title>Scenario-first Sunday comparison</title><style>body{font:15px system-ui;margin:24px;line-height:1.5}table{border-collapse:collapse}td,th{padding:10px;border:1px solid #ccc;vertical-align:top}.scroll{overflow:auto}</style></head><body><h1>Scenario-first Sunday Main</h1><p><strong>PRELIMINARY RESEARCH — NOT ENTRY CLEARED</strong></p>'+''.join(tables)+'<p><a href="LINEUP_COMPARISON.md">Allocation, exposures and full review</a> · <a href="comparison.json">Machine evidence</a></p></body></html>');print(json.dumps(checks))
if __name__=='__main__':main()
